def canonical(o): return json.dumps(o,ensure_ascii=False,sort_keys=True,separators=(',',':'))
def sha(o): return hashlib.sha256(canonical(o).encode()).hexdigest()
def A(asset_id,family,caps,anchor,path,bridge,cue,reconstruct,contrast,worked,wrong,discriminator,repair,verify,fade,transfer,limits,topics=None,app=None):
    x={"asset_id":asset_id,"family":family,"version":"1.0.0","subject_scope":"CHEMISTRY","topic_scope_refs":topics or [],"capability_refs":caps,"applicability_conditions":app or ["Use only when the bound capability is required by the current LearnerStudyModel."],"familiar_macro_anchor":anchor,"particle_symbolic_representation_path":path,"ordinary_language_bridge":bridge,"rule_model_condition_cue":cue,"reconstruction_route":reconstruct,"minimal_contrast":contrast,"worked_example_family":worked,"common_wrong_model":wrong,"misconception_discriminator":discriminator,"repair_route":repair,"verification_method":verify,"fading_dimensions":fade,"transfer_family":transfer,"known_limitations":limits,"evidence_class":"INDEPENDENT_SUBJECT_PCK_PILOT","provenance":PROVENANCE,"raw_mature_reference_used":False,"promotion_authority":AUTHORITY,"asset_digest":""}
    y=copy.deepcopy(x); y.pop('asset_digest'); x['asset_digest']=sha(y); return x

